import java.util.ArrayList;
import java.util.List;

public final class Solution {
    private Solution() {}

    public enum Orientation { HORIZONTAL, VERTICAL }
    public enum Shot { MISS, HIT, SUNK, REPEAT }

    public static final class Board {
        private final int size;
        private final int[][] ships;
        private final boolean[][] attacked;
        private final List<Integer> remaining = new ArrayList<>();

        private Board(int size) {
            this.size = size;
            this.ships = new int[size][size];
            this.attacked = new boolean[size][size];
        }
    }

    public static Board createBoard(int size) {
        if (size < 2 || size > 26) throw new IllegalArgumentException("invalid size");
        return new Board(size);
    }

    public static void place(Board board, String start, int length, Orientation orientation) {
        requireBoard(board);
        if (orientation == null || length < 1 || length > board.size) throw new IllegalArgumentException("invalid placement");
        int[] p = coordinate(board, start);
        int dr = orientation == Orientation.VERTICAL ? 1 : 0;
        int dc = orientation == Orientation.HORIZONTAL ? 1 : 0;
        int endRow = p[0] + dr * (length - 1);
        int endCol = p[1] + dc * (length - 1);
        if (endRow >= board.size || endCol >= board.size) throw new IllegalArgumentException("placement exceeds board");
        for (int i = 0; i < length; i++) {
            if (board.ships[p[0] + dr * i][p[1] + dc * i] != 0) throw new IllegalArgumentException("overlap");
        }
        int id = board.remaining.size() + 1;
        board.remaining.add(length);
        for (int i = 0; i < length; i++) board.ships[p[0] + dr * i][p[1] + dc * i] = id;
    }

    public static Shot attack(Board board, String cell) {
        requireBoard(board);
        int[] p = coordinate(board, cell);
        if (board.attacked[p[0]][p[1]]) return Shot.REPEAT;
        board.attacked[p[0]][p[1]] = true;
        int id = board.ships[p[0]][p[1]];
        if (id == 0) return Shot.MISS;
        int left = board.remaining.get(id - 1) - 1;
        board.remaining.set(id - 1, left);
        return left == 0 ? Shot.SUNK : Shot.HIT;
    }

    public static boolean allSunk(Board board) {
        requireBoard(board);
        for (int cells : board.remaining) if (cells != 0) return false;
        return true;
    }

    public static String[] renderShots(Board board) {
        requireBoard(board);
        String[] result = new String[board.size];
        for (int r = 0; r < board.size; r++) {
            StringBuilder row = new StringBuilder(board.size);
            for (int c = 0; c < board.size; c++) {
                row.append(!board.attacked[r][c] ? '.' : board.ships[r][c] == 0 ? 'o' : 'x');
            }
            result[r] = row.toString();
        }
        return result;
    }

    private static int[] coordinate(Board board, String cell) {
        if (cell == null || !cell.matches("[A-Z](?:[1-9]|[1-9]\\d+)")) throw new IllegalArgumentException("malformed coordinate");
        int row = cell.charAt(0) - 'A';
        int column;
        try { column = Integer.parseInt(cell.substring(1)) - 1; }
        catch (NumberFormatException ex) { throw new IllegalArgumentException("malformed coordinate"); }
        if (row < 0 || row >= board.size || column < 0 || column >= board.size) throw new IllegalArgumentException("coordinate outside board");
        return new int[] {row, column};
    }

    private static void requireBoard(Board board) {
        if (board == null) throw new IllegalArgumentException("board is null");
    }
}

