public class SolutionTest {
    interface Action { void run(); }

    public static void main(String[] args) {
        expect(IllegalArgumentException.class, () -> Solution.createBoard(1));
        expect(IllegalArgumentException.class, () -> Solution.createBoard(27));
        Solution.Board empty = Solution.createBoard(2);
        check(!Solution.allSunk(empty), "board without ships must not be all sunk");
        rows(Solution.renderShots(empty), "..", "..");

        expect(IllegalArgumentException.class, () -> Solution.place(null, "A1", 1, Solution.Orientation.HORIZONTAL));
        expect(IllegalArgumentException.class, () -> Solution.attack(null, "A1"));
        expect(IllegalArgumentException.class, () -> Solution.allSunk(null));
        expect(IllegalArgumentException.class, () -> Solution.renderShots(null));

        Solution.Board board = Solution.createBoard(4);
        Solution.place(board, "A1", 2, Solution.Orientation.HORIZONTAL);
        Solution.place(board, "C3", 2, Solution.Orientation.HORIZONTAL);
        rows(Solution.renderShots(board), "....", "....", "....", "....");
        check(!Solution.allSunk(board), "unhit fleet reported sunk");

        eq(Solution.Shot.MISS, Solution.attack(board, "B1"));
        eq(Solution.Shot.HIT, Solution.attack(board, "A1"));
        eq(Solution.Shot.REPEAT, Solution.attack(board, "A1"));
        eq(Solution.Shot.SUNK, Solution.attack(board, "A2"));
        check(!Solution.allSunk(board), "second ship is still afloat");
        eq(Solution.Shot.HIT, Solution.attack(board, "C3"));
        eq(Solution.Shot.SUNK, Solution.attack(board, "C4"));
        check(Solution.allSunk(board), "all ships should be sunk");
        rows(Solution.renderShots(board), "xx..", "o...", "..xx", "....");

        String[] rendered = Solution.renderShots(board);
        rendered[0] = "changed";
        rows(Solution.renderShots(board), "xx..", "o...", "..xx", "....");

        Solution.Board vertical = Solution.createBoard(3);
        Solution.place(vertical, "A3", 3, Solution.Orientation.VERTICAL);
        eq(Solution.Shot.HIT, Solution.attack(vertical, "A3"));
        eq(Solution.Shot.HIT, Solution.attack(vertical, "B3"));
        eq(Solution.Shot.SUNK, Solution.attack(vertical, "C3"));

        Solution.Board atomic = Solution.createBoard(3);
        Solution.place(atomic, "B2", 1, Solution.Orientation.HORIZONTAL);
        expect(IllegalArgumentException.class, () -> Solution.place(atomic, "A2", 3, Solution.Orientation.VERTICAL));
        Solution.place(atomic, "A2", 1, Solution.Orientation.HORIZONTAL);
        Solution.place(atomic, "C2", 1, Solution.Orientation.HORIZONTAL);

        Solution.Board bounds = Solution.createBoard(26);
        Solution.place(bounds, "Z26", 1, Solution.Orientation.VERTICAL);
        eq(Solution.Shot.SUNK, Solution.attack(bounds, "Z26"));

        Solution.Board invalid = Solution.createBoard(3);
        for (String cell : new String[] {null, "", "A", "1", "a1", "A0", "A01", "A4", "D1", "AA1", "A 1", "A+1"}) {
            expect(IllegalArgumentException.class, () -> Solution.attack(invalid, cell));
        }
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, null, 1, Solution.Orientation.HORIZONTAL));
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, "A1", 0, Solution.Orientation.HORIZONTAL));
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, "A1", -1, Solution.Orientation.HORIZONTAL));
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, "A1", 4, Solution.Orientation.HORIZONTAL));
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, "A1", 1, null));
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, "A3", 2, Solution.Orientation.HORIZONTAL));
        expect(IllegalArgumentException.class, () -> Solution.place(invalid, "C1", 2, Solution.Orientation.VERTICAL));
    }

    static void rows(String[] actual, String... expected) {
        check(actual != null, "render returned null");
        if (actual.length != expected.length) throw new AssertionError("Wrong row count");
        for (int i = 0; i < expected.length; i++) {
            if (!expected[i].equals(actual[i]))
                throw new AssertionError("Row " + i + ": expected " + expected[i] + " but got " + actual[i]);
        }
    }
    static void expect(Class<? extends Throwable> type, Action action) {
        try { action.run(); }
        catch (Throwable t) {
            if (type.isInstance(t)) return;
            throw new AssertionError("Expected " + type.getName() + " but got " + t, t);
        }
        throw new AssertionError("Expected " + type.getName());
    }
    static void eq(Object expected, Object actual) {
        if (!expected.equals(actual)) throw new AssertionError("Expected " + expected + " but got " + actual);
    }
    static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

